import React, { useState } from 'react';
// Importamos la función que te faltaba y el "auth" de tu configuración
import { signInWithEmailAndPassword } from 'firebase/auth';
import { auth } from '../firebase-config'; 

const LogIn = ({ onLogin, isOnline, apiBaseUrl }) => {
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');

    const manejarSubmit = async (e) => {
    e.preventDefault();
    if (!isOnline) return; // Requisito 5.3: No funciona sin conexión [cite: 197]

    try {
    const userCredential = await signInWithEmailAndPassword(auth, email, password);
    const user = userCredential.user;

    const response = await fetch(`${apiBaseUrl}/usuarios/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include', // Para guardar la sesión en el servidor [cite: 188]
        body: JSON.stringify({ email: user.email }),
    });

    if (response.ok) {
        const datosServidor = await response.json();
        onLogin(datosServidor); // Esto avisa a App.js que ya estamos dentro
    }
    } catch (err) {
        setError("Error al entrar: revisa tus datos");
    }
    };

    return (
    <div className="card p-3 shadow-sm">
    <h4 className="text-center">Inicio de sesión</h4>
    <form onSubmit={manejarSubmit}>
        {error && <p style={{color: 'red'}}>{error}</p>}
        <div className="mb-2">
        <label>Email</label>
        <input 
            type="email" 
            className="form-control" 
            value={email} 
            onChange={(e) => setEmail(e.target.value)} 
            required 
          />
        </div>
        <div className="mb-3">
          <label>Contraseña</label>
          <input 
            type="password" 
            className="form-control" 
            value={password} 
            onChange={(e) => setPassword(e.target.value)} 
            required 
          />
        </div>
        <button 
          type="submit" 
          className="btn btn-primary w-100" 
          disabled={!isOnline} 
        >
          Autenticarse
        </button>
      </form>
    </div>
  );
};

export default LogIn;
